// 6. 기본 문항 배점 Fallback (사설 모의고사 및 기본 폼용)
export const DEFAULT_QUESTION_SCORES = EXAM_QUESTION_SCORES['2025_csat'];

// 7. 시험 회차, 과목 및 선택과목별 문항 배점 동적 산출 유틸
export const getQuestionScores = (examId = '2025_csat', subjectKey = 'korean', optionKey = 'speech') => {
  const exam = EXAM_QUESTION_SCORES[examId] || EXAM_QUESTION_SCORES['2025_csat'];
  const sub = exam[subjectKey] || EXAM_QUESTION_SCORES['2025_csat'][subjectKey];
  if (!sub) return [];
  if (Array.isArray(sub)) return sub;
  return sub[optionKey] || Object.values(sub)[0] || [];
};

// 8. 시험 회차, 과목 및 선택과목별 문항 메타(정답률/난이도) 추출 유틸
export const getQuestionMetas = (examId = '2025_csat', subjectKey = 'korean', optionKey = 'speech') => {
  const exam = EXAM_QUESTION_METAS[examId] || EXAM_QUESTION_METAS['2025_csat'];
  const sub = exam[subjectKey] || EXAM_QUESTION_METAS['2025_csat'][subjectKey];
  if (!sub) return [];
  if (Array.isArray(sub)) return sub;
  return sub[optionKey] || Object.values(sub)[0] || [];
};

// 9. 시험 회차 및 선택과목에 맞는 공식 정답표 추출 유틸
export const getOfficialAnswers = (examId = '2025_csat', subjectKey = 'korean', optionKey = 'speech') => {
  const exam = OFFICIAL_ANSWER_KEYS[examId];
  if (!exam) return null;
  const sub = exam[subjectKey];
  if (!sub) return null;
  if (Array.isArray(sub)) return sub;
  return sub[optionKey] || Object.values(sub)[0] || null;
};

// 10. 점수 기준 등급 판정 유틸 함수
export const calculateGradeByScore = (examId, subjectKey, optionKey, score) => {
  const exam = EXAM_CUTOFFS[examId] || EXAM_CUTOFFS['2025_csat'];
  const subData = exam[subjectKey] || exam['korean'];

  let cuts = [90, 80, 70, 60];
  let optionName = '';

  if (subData.isAbsolute) {
    cuts = subData.cuts || [90, 80, 70, 60];
  } else if (subData.options) {
    const opt = subData.options[optionKey] || Object.values(subData.options)[0];
    cuts = opt.cuts;
    optionName = opt.name;
  } else if (subData.cuts) {
    cuts = subData.cuts;
  }

  // 등급 계산 (1~9등급)
  let grade = 5;
  if (score >= cuts[0]) grade = 1;
  else if (score >= cuts[1]) grade = 2;
  else if (score >= cuts[2]) grade = 3;
  else if (score >= cuts[3]) grade = 4;
  else grade = 5;

  const cut1 = cuts[0];
  const deltaFromCut1 = score - cut1;

  // 예상 백분위 추정치 계산
  let percentile = 60;
  if (grade === 1) {
    percentile = Math.min(100, Math.round(96 + ((score - cut1) / Math.max(1, (subData.totalScore || 100) - cut1)) * 4));
  } else if (grade === 2) {
    percentile = Math.min(95, Math.round(89 + ((score - cuts[1]) / Math.max(1, cut1 - cuts[1])) * 6));
  } else if (grade === 3) {
    percentile = Math.min(88, Math.round(77 + ((score - cuts[2]) / Math.max(1, cuts[1] - cuts[2])) * 11));
  } else if (grade === 4) {
    percentile = Math.min(76, Math.round(60 + ((score - cuts[3]) / Math.max(1, cuts[2] - cuts[3])) * 16));
  } else {
    percentile = Math.max(10, Math.round((score / Math.max(1, cuts[3])) * 50));
  }

  return {
    grade,
    cut1,
    cuts,
    deltaFromCut1,
    percentile,
    optionName,
    totalScore: subData.totalScore || 100
  };
};

